<?php $title='Overview'; require 'header.php'; $d=db(); $jobs=(int)$d->query("SELECT COUNT(*) c FROM jobs WHERE status='open'")->fetch_assoc()['c'];$cands=(int)$d->query("SELECT COUNT(*) c FROM candidates")->fetch_assoc()['c'];$new=(int)$d->query("SELECT COUNT(*) c FROM candidates WHERE status='new'")->fetch_assoc()['c'];$int=(int)$d->query("SELECT COUNT(*) c FROM candidates WHERE status='interview'")->fetch_assoc()['c']; ?>
<div class="admin-head"><div><span class="eyebrow">RECRUITING OS</span><h1>Good hiring starts with a clear pipeline.</h1></div><a class="btn dark" href="candidates.php">Review candidates</a></div>
