<section class="admin-panel"><div class="panel-head"><h2>Recent applications</h2><a href="candidates.php">View all →</a></div><table><thead><tr><th>Candidate</th><th>Role</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody><?php $rs=$d->query("SELECT c.*,j.title FROM candidates c JOIN jobs j ON j.id=c.job_id ORDER BY c.created_at DESC LIMIT 8");while($r=$rs->fetch_assoc()):?><tr><td><strong><?=e($r['first_name'].' '.$r['last_name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><span class="status-pill <?=e($r['status'])?>"><?=e(status_label($r['status']))?></span></td><td><?=e(date('M j, Y',strtotime($r['created_at'])))?></td><td><a href="candidate.php?id=<?=$r['id']?>">Open</a></td></tr><?php endwhile;?></tbody></table></section><?php require 'footer.php'; ?>